function stageStates(project,progress,stages){

  return stages.map(([key],index)=>project.stageStates?.[key]||(index<progress.completed?'Completed':index<progress.completed+progress.inprogress?'In progress':'Not started'));

}

function rail(states,stages,esc){return `<div class="study-stage-rail" role="img" aria-label="${esc(states.map((state,index)=>stages[index][1]+': '+state).join(', '))}">${states.map((state,index)=>`<span class="${state==='Completed'?'stage-done':state==='In progress'?'stage-current':'stage-empty'}" title="${esc(stages[index][1]+': '+state)}"></span>`).join('')}</div>`;}

export function cardView(project,{portfolio,progressFor,stages,icon,esc,badge}){

  const context=portfolio.contexts[project.id],files=context?.files?.length??project.sourceCount??0,progress=progressFor(project);

  return `<article class="project-card study-card"><div class="study-card-heading"><span class="study-emblem">${icon(project.demo?'map':'layers')}</span><span class="study-kind">${esc(project.type)}</span><div class="study-card-actions"><button class="favorite ${project.favorite?'is-favorite':''}" data-favorite="${project.id}" aria-label="${project.favorite?'Unfavorite':'Favorite'} ${esc(project.name)}" aria-pressed="${!!project.favorite}">${project.favorite?'★':'☆'}</button><button class="study-more" data-projectmenu="${project.id}" aria-label="Manage ${esc(project.name)}"><span aria-hidden="true">···</span></button></div></div><div class="study-title-row"><h2>${esc(project.name)}</h2>${badge(project.demo?'Illustrative':project.status,project.demo?'gray':project.status==='Active'?'green':'gray')}</div><p class="project-description">${esc(project.description||'Add a description to give this study a little context.')}</p><div class="project-location">${icon('pin')}${esc(project.location||'Location not specified')}</div><div class="study-progress"><div><span>Workflow tracking</span><button data-progress="${project.id}" aria-label="Update progress for ${esc(project.name)}">Update ${icon('chevron')}</button></div>${rail(stageStates(project,progress,stages),stages,esc)}<span class="study-progress-caption"><strong>${progress.completed} of ${progress.total}</strong> stages complete${project.demo?' · Illustrative':''}</span></div><div class="study-evidence"><span>${icon('pin')}<strong>${context?.wellDrafts?.length??project.wellCount??0}</strong> wells${project.demo?' · example':''}</span><span>${icon('file')}<strong>${files}</strong> source files</span></div><div class="project-card-bottom"><span>Updated ${new Date(project.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>${project.status!=='Trash'?`<button class="study-open" data-openproject="${project.id}">Open project ${icon('arrow')}</button>`:`<button class="study-open" data-projectmenu="${project.id}">Restore project ${icon('arrow')}</button>`}</div></article>`;

}

export function insightsView({portfolio,progressFor,icon,esc}){

  const active=portfolio.records.filter(project=>project.status==='Active');

  const progress=active.reduce((sum,project)=>{const x=progressFor(project);return {completed:sum.completed+x.completed,inprogress:sum.inprogress+x.inprogress,notstarted:sum.notstarted+x.notstarted};},{completed:0,inprogress:0,notstarted:0});

  const total=progress.completed+progress.inprogress+progress.notstarted;

  const recent=portfolio.records.filter(project=>project.status==='Active').sort((a,b)=>(b.lastOpenedAt||b.updatedAt).localeCompare(a.lastOpenedAt||a.updatedAt))[0];

  return `<div class="study-overview"><section class="study-workflow" aria-labelledby="workflow-heading"><div class="study-section-head"><h2 id="workflow-heading">Portfolio progress</h2><span>${active.length} active ${active.length===1?'study':'studies'}</span></div><div class="study-workflow-values">${[['completed','Completed'],['inprogress','In progress'],['notstarted','Not started']].map(([key,title])=>`<div><span class="workflow-dot ${key}"></span><strong>${progress[key]}</strong><span>${title}</span></div>`).join('')}</div><div class="study-total-rail" role="img" aria-label="${progress.completed} completed, ${progress.inprogress} in progress, ${progress.notstarted} not started workflow stages">${[['completed','Completed'],['inprogress','In progress'],['notstarted','Not started']].map(([key])=>`<span class="${key}" style="width:${total?progress[key]/total*100:0}%"></span>`).join('')}</div><p>${active.some(project=>project.demo)?'Includes illustrative progress.':'Recorded activity and user-reported stages.'} Tracking status is separate from scientific approval.</p></section><section class="study-resume"><div class="resume-symbol">${icon('layers')}</div><div><span class="study-kicker">CONTINUE WORKING</span><h2>${esc(recent?.name||'Start your first study')}</h2><p>${esc(recent?.location||'Bring your sources and interpretation into one project.')}</p></div>${recent?`<button data-openproject="${recent.id}" aria-label="Continue ${esc(recent.name)}">${icon('arrow')}</button>`:'<button data-action="new-project" aria-label="Create a project">'+icon('plus')+'</button>'}</section></div>`;

}

export function directoryView({records,portfolio,projectFilter,projectQuery,projectView,projectSort,projectCard,projectActions,projectInsights,profileMenu,icon,esc}){

  const counts={All:portfolio.records.filter(p=>p.status!=='Trash').length,Active:portfolio.records.filter(p=>p.status==='Active').length,Favorites:portfolio.records.filter(p=>p.favorite&&p.status!=='Trash').length,Archived:portfolio.records.filter(p=>p.status==='Archived').length,Trash:portfolio.records.filter(p=>p.status==='Trash').length};

  const filters=[['All','All projects','layers'],['Active','Active studies','overview'],['Favorites','Favorites','star'],['Archived','Archived','clock'],['Trash','Trash','trash']];

  return `<div class="portfolio-shell study-library"><aside class="study-sidebar"><a class="brand" href="#home" aria-label="StrataX home"><img src="logo.png" alt="StrataX logo"><div>StrataX<small>Subsurface workspace</small></div></a><div class="library-label">PROJECT LIBRARY</div><nav aria-label="Project library">${filters.map(([filter,title,symbol])=>`<button data-projectfilter="${filter}" class="${projectFilter===filter?'selected':''}" ${projectFilter===filter?'aria-current="page"':''}>${icon(symbol)}<span>${title}</span><small>${counts[filter]}</small></button>`).join('')}</nav><div class="library-bottom"><button data-go="catalog">${icon('layers')}Feature inventory</button><button data-action="help">${icon('help')}Help & shortcuts</button><div class="library-storage">${icon('shield')}<span>Project storage<small>Cloud or local folder</small></span></div></div></aside><div class="study-stage"><header class="portfolio-header study-header"><div class="study-breadcrumb"><a href="#home">Workspace</a><span>/</span><strong>Projects</strong></div><div class="actions"><a class="study-help" href="mailto:contact@terracodeanalytics.com">${icon('help')}<span>Support</span></a>${profileMenu()}</div></header><main class="portfolio-main"><div class="study-page-heading"><div><div class="study-kicker">YOUR WORKSPACE</div><h1>Projects<span>${counts.All}</span></h1><p>Your studies, sources and next steps. All in one place.</p></div><div class="actions"><button data-action="open-local">Open local project</button><button data-action="import-package">Import project file</button><button class="primary study-create" data-action="new-project">${icon('plus')}New project</button></div></div>${projectInsights()}<section class="study-projects" aria-labelledby="project-list-heading"><div class="study-list-heading"><h2 id="project-list-heading">${esc(projectFilter==='All'?'All projects':projectFilter==='Active'?'Active studies':projectFilter)}<span>${records.length}</span></h2><div class="study-display-controls"><button data-projectview="grid" aria-label="Grid view" aria-pressed="${projectView==='grid'}">${icon('overview')}</button><button data-projectview="list" aria-label="List view" aria-pressed="${projectView==='list'}">${icon('data')}</button></div></div><div class="portfolio-tools"><label class="project-search">${icon('search')}<input id="project-search" aria-label="Search projects" placeholder="Search by project or location…" value="${esc(projectQuery)}"></label><label class="study-sort"><span>Sort by</span><select id="project-sort" aria-label="Sort projects"><option value="recent" ${projectSort==='recent'?'selected':''}>Recently updated</option><option value="name" ${projectSort==='name'?'selected':''}>Name A–Z</option><option value="created" ${projectSort==='created'?'selected':''}>Newest first</option></select></label></div>${records.length?(projectView==='grid'?`<div class="project-grid">${records.map(projectCard).join('')}</div>`:`<div class="panel table-wrap study-table"><table><thead><tr><th>Project</th><th>Location</th><th>Type</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${records.map(p=>`<tr><td><button class="quiet" data-openproject="${p.id}">${esc(p.name)}</button></td><td>${esc(p.location||'Not specified')}</td><td>${esc(p.type)}</td><td>${esc(p.demo?'Illustrative':p.status)}</td><td>${new Date(p.updatedAt).toLocaleDateString()}</td><td>${projectActions(p)}</td></tr>`).join('')}</tbody></table></div>`):`<div class="portfolio-empty"><span class="study-empty-icon">${icon(projectQuery?'search':'layers')}</span><h2>${projectQuery?'No projects found':projectFilter==='Active'?'Make room for your next study':'No '+projectFilter.toLowerCase()+' projects'}</h2><p>${projectQuery?'Try a different project name or location.':projectFilter==='Trash'?'Projects moved to Trash will appear here for restoration.':'Create a project to organize your sources and interpretation.'}</p>${projectQuery?'<button id="clear-project-search">Clear search</button>':'<button class="primary" data-action="new-project">'+icon('plus')+'New project</button>'}</div>`}</section><footer class="portfolio-footer"><span>StrataX <i>·</i> Evidence-led subsurface interpretation</span><span>${icon('shield')}Saved to each project’s chosen destination</span></footer></main></div></div>`;

}
